import React, { useState, useEffect } from 'react';
import './App.css';
import axios from 'axios';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

// Import components
import Dashboard from './components/Dashboard';
import DataManagement from './components/DataManagement';
import ModelTraining from './components/ModelTraining';
import Predictions from './components/Predictions';
import Recommendations from './components/Recommendations';

const API_URL = 'http://localhost:5000/api';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [systemStatus, setSystemStatus] = useState({
    datasetLoaded: false,
    trainingStatus: {
      sarima: 'Not Trained',
      lstm: 'Not Trained',
      hybrid: 'Not Trained'
    }
  });

  useEffect(() => {
    checkSystemStatus();
  }, []);

  const checkSystemStatus = async () => {
    try {
      const response = await axios.get(`${API_URL}/status`);
      setSystemStatus(response.data);
    } catch (error) {
      console.error('Error checking system status:', error);
      toast.error('Failed to connect to server');
    }
  };

  const renderTabContent = () => {
    switch(activeTab) {
      case 'dashboard':
        return <Dashboard systemStatus={systemStatus} />;
      case 'data':
        return <DataManagement onDataUpload={checkSystemStatus} />;
      case 'training':
        return <ModelTraining onTrainingComplete={checkSystemStatus} />;
      case 'predictions':
        return <Predictions />;
      case 'recommendations':
        return <Recommendations />;
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>🌾 ClimaYield-X</h1>
        <p className="subtitle">Smart Agricultural Forecasting & Decision Support System</p>
      </header>

      <nav className="nav-tabs">
        <button 
          className={activeTab === 'dashboard' ? 'active' : ''}
          onClick={() => setActiveTab('dashboard')}
        >
          📊 Dashboard
        </button>
        <button 
          className={activeTab === 'data' ? 'active' : ''}
          onClick={() => setActiveTab('data')}
        >
          📁 Data Management
        </button>
        <button 
          className={activeTab === 'training' ? 'active' : ''}
          onClick={() => setActiveTab('training')}
        >
          🤖 Model Training
        </button>
        <button 
          className={activeTab === 'predictions' ? 'active' : ''}
          onClick={() => setActiveTab('predictions')}
        >
          📈 Predictions
        </button>
        <button 
          className={activeTab === 'recommendations' ? 'active' : ''}
          onClick={() => setActiveTab('recommendations')}
        >
          💡 Recommendations
        </button>
      </nav>

      <main className="main-content">
        {renderTabContent()}
      </main>

      <ToastContainer position="bottom-right" />
    </div>
  );
}

export default App;
